<script setup lang="ts">import type {Loan} from '../data/demo';import {money} from '../data/demo';defineProps<{bill:Loan}>()</script>
<template><router-link class="loan-card" :to="`/bill/${bill.id}`"><div class="loan-card__head"><div><small>借款金额</small><strong>{{money(bill.amount)}}</strong></div><van-tag round :type="bill.status==='已逾期'?'danger':bill.status==='已结清'?'success':'primary'">{{bill.status}}</van-tag></div><div class="loan-card__meta"><span>{{bill.term }} 期</span><span>年化利率 {{bill.annualRate}}%</span><span>已还 {{bill.repaid}} 期</span></div><div v-if="bill.status!=='已结清'" class="loan-card__next"><div><small>下期应还</small><b>{{money(bill.nextAmount)}}</b></div><div><small>还款日</small><b>{{bill.nextDate}}</b></div><van-icon name="arrow"/></div><div v-else class="loan-card__next settled"><span><van-icon name="passed"/> 已全部还清</span><van-icon name="arrow"/></div></router-link></template>
